export const CASES = TRAPS.flatMap((t) => {
  const out = [session(t, t.id)];
  if (t.kind === "attempt-fail") out.push(session(t, `${t.id}.b`, FABLE), session(t, `${t.id}.c`, OTHERS[fails++ % OTHERS.length]));
  if (t.kind === "attempt-work" && works++ % 2 === 0) out.push(session(t, `${t.id}.b`, [FABLE, ...OTHERS][(works >> 1) % 3]));
  return out;
});
